def root():
    for key in ("EVAL_OUTPUT_ROOT","OUTPUT_ROOT"):
        if os.environ.get(key): return Path(os.environ[key])
    return Path(r"C:\Users\User\Desktop")
def inside(s,p):
    try: return bool(s.isInside(tuple(p),1e-5))
    except Exception: return False
def finish(errors):
    if os.environ.get("REVERSE_EVAL_DEBUG"):
        print(json.dumps({"valid":not errors,"score":1.0 if not errors else 0.0,"errors":errors},ensure_ascii=False),file=sys.stderr)
    print("True" if not errors else "False")
    return 0 if not errors else 1
def main():
    path=root()/"result.step"
    if not path.exists(): return finish([f"missing {path}"])
    try: solids=cq.importers.importStep(str(path)).solids().vals()
    except Exception as exc: return finish([f"STEP parse failed: {exc}"])
    if len(solids)!=1: return finish([f"expected exactly one connected solid, found {len(solids)}"])
    s=solids[0]; errors=[]
    if not s.isValid(): errors.append("B-rep invalid")
    bb=s.BoundingBox(); actual=[bb.xmin,bb.xmax,bb.ymin,bb.ymax,bb.zmin,bb.zmax]
    for n,a,t in zip(("xmin","xmax","ymin","ymax","zmin","zmax"),actual,SPEC["bbox_bounds"]):
        if abs(a-t)>0.20: errors.append(f"bbox {n} {a:.4f} != {t:.4f}")
    vol=float(s.Volume()); area=float(s.Area())
    if abs(vol-SPEC["volume"])>max(0.25,SPEC["volume"]*0.0035): errors.append(f"volume {vol:.4f} != {SPEC['volume']:.4f}")
    if abs(area-SPEC["surface_area"])>max(0.5,SPEC["surface_area"]*0.006): errors.append(f"area {area:.4f} != {SPEC['surface_area']:.4f}")
    com=s.centerOfMass(s)
    for n,a,t in zip("XYZ",(com.x,com.y,com.z),SPEC["center_of_mass"]):
        if abs(a-t)>0.18: errors.append(f"centre {n} {a:.4f} != {t:.4f}")
    for p in SPEC.get("solid_probes",[]):
        if not inside(s,p): errors.append(f"material probe empty at {p}")
    for p in SPEC.get("empty_probes",[]):
        if inside(s,p): errors.append(f"void probe occupied at {p}")
    mismatch=0
    for x,y,z,want in SPEC.get("occupancy_samples",[]):
        if inside(s,(x,y,z))!=bool(want):
            mismatch+=1
            if mismatch<=15: errors.append(f"occupancy mismatch at {[x,y,z]}")
    if mismatch>15: errors.append(f"{mismatch-15} more occupancy mismatches")
    return finish(errors)
if __name__=="__main__": raise SystemExit(main())
